sp_header_footer.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_header_footer.css:
.cp-header {
  display: flex; align-items: center; gap: 28px;
  padding: 0 28px; height: 64px;
  background: var(--cp-navy);
  border-bottom: 2px solid var(--cp-gold);
}
.cp-header__brand img { height: 28px; }
.cp-header__nav { display: flex; gap: 22px; margin-left: 12px; }
.cp-header__nav a {
  color: #cdd7e4; font-weight: 650; font-size: 14px; text-decoration: none;
  padding: 6px 0; border-bottom: 2px solid transparent; transition: .15s;
}
.cp-header__nav a:hover { color: #fff; border-bottom-color: var(--cp-gold); }
.cp-header__user { margin-left: auto; display: flex; align-items: center; gap: 14px; color: #cdd7e4; font-size: 13px; }
.cp-header__user a { color: var(--cp-gold); text-decoration: none; font-weight: 700; }
@media (max-width: 760px) {
  .cp-header { height: auto; flex-wrap: wrap; padding: 12px 16px; gap: 12px; }
  .cp-header__nav { order: 3; width: 100%; overflow-x: auto; }
}
